[Загружен файл: patch_optimization_skill.json]
```json
{
  "skill_id": "PATCH-OPTIMIZATION-001",
  "name": "📦 Оптимизация патчей для больших изменений",
  "version": "1.0",
  "created": "2026-02-28",
  "status": "active",
  "description": "Как делать большие патчи без обрезки ответов",

  "problem": {
    "issue": "При создании больших патчей (особенно для новых модулей) ответ может обрезаться",
    "why": "Хотя max_tokens=16384, длинные JSON в 'content' занимают много токенов",
    "solution": "Использовать компактный JSON без лишних пробелов и переносов"
  },

  "limits_increased": {
    "max_tokens": "16384 токенов (максимум для Grok)",
    "timeout": "300 секунд (5 минут)",
    "chunk_size": "500 символов (было 50)",
    "note": "Это позволяет патчам до ~50KB текста"
  },

  "optimization_techniques": {
    "technique_1": {
      "name": "Минифицированный JSON",
      "description": "Убрать все лишние пробелы и переносы из content",
      "bad_example": {
        "content": "{\n  \"identity\": {\n    \"module_id\": \"TASKS-001\",\n    \"name\": \"Tasks\"\n  },\n  \"tasks\": []\n}"
      },
      "good_example": {
        "content": "{\"identity\":{\"module_id\":\"TASKS-001\",\"name\":\"Tasks\"},\"tasks\":[]}"
      },
      "savings": "60-70% размера для больших JSON"
    },

    "technique_2": {
      "name": "Поэтапное создание",
      "description": "Создавать большие модули в несколько шагов",
      "steps": [
        "1. Создать модуль с минимальной структурой (только identity + meta)",
        "2. Добавить данные через JSON patches (add операции)",
        "3. При необходимости добавить ещё данные"
      ],
      "example": {
        "step_1": {
          "description": "Создать пустой модуль",
          "patch": {
            "file_path": "simbiosis/large_module.json",
            "content": "{\"identity\":{\"module_id\":\"LARGE-001\",\"name\":\"Big Module\",\"version\":\"1.0\"},\"meta\":{\"description\":\"Large dataset\",\"status\":\"active\"},\"data\":[]}",
            "description": "Создание базовой структуры"
          }
        },
        "step_2": {
          "description": "Добавить данные частями",
          "patch": {
            "file_path": "simbiosis/large_module.json",
            "changes": [
              {
                "op": "add",
                "path": "data",
                "value": {"id": "item-1", "content": "..."}
              },
              {
                "op": "add",
                "path": "data",
                "value": {"id": "item-2", "content": "..."}
              }
            ],
            "description": "Добавление первых элементов"
          }
        }
      }
    },

    "technique_3": {
      "name": "Использовать ID вместо полных объектов",
      "description": "Для справочных данных хранить только ID и ссылку",
      "bad_example": {
        "tasks": [
          {
            "id": "TASK-001",
            "title": "Very long task description that takes many tokens...",
            "details": "Even longer details with many words and explanations...",
            "assignee": {"name": "John", "email": "john@example.com", "role": "developer"}
          }
        ]
      },
      "good_example": {
        "tasks": [
          {
            "id": "TASK-001",
            "title": "Task title",
            "details_ref": "docs/task-001.md"
          }
        ],
        "note": "Полное описание в отдельном файле или модуле"
      }
    },

    "technique_4": {
      "name": "Разбить на несколько модулей",
      "description": "Вместо одного огромного модуля сделать несколько маленьких",
      "example": {
        "instead_of": "simbiosis/all_data.json (1000 записей)",
        "use": [
          "simbiosis/data_core.json (основные 50 записей)",
          "simbiosis/data_extended.json (дополнительные 500)",
          "simbiosis/data_archive.json (старые 450)"
        ]
      }
    }
  },

  "best_practices_for_large_patches": [
    "✅ ВСЕГДА минифицируй JSON в content (убери \\n и лишние пробелы)",
    "✅ Для больших модулей: создавай пустую структуру → заполняй через JSON patches",
    "✅ Используй короткие ключи и значения где возможно",
    "✅ Разбивай большие массивы на части (добавляй по 10-20 элементов за раз)",
    "✅ Выноси большие текстовые данные в отдельные файлы .md или .txt",
    "❌ НЕ создавай модули >100KB за один раз",
    "❌ НЕ дублируй данные между модулями",
    "❌ НЕ храни огромные тексты в JSON (используй ссылки на файлы)"
  ],

  "json_minification": {
    "how_to": "Используй JSON.stringify() без pretty-print",
    "python_example": "json.dumps(data, separators=(',', ':'))",
    "javascript_example": "JSON.stringify(data)",
    "manual": "Убери все \\n, убери пробелы после : и ,",
    "before": "{\n  \"key\": \"value\",\n  \"array\": [\n    1,\n    2\n  ]\n}",
    "after": "{\"key\":\"value\",\"array\":[1,2]}"
  },

  "when_patch_is_too_large": {
    "problem": "Патч всё равно обрезается даже после минификации",
    "solutions": [
      {
        "option": "1. Разбить на несколько патчей",
        "description": "Вместо 1 большого → 3 маленьких",
        "example": "Создать базу → Добавить часть А → Добавить часть Б"
      },
      {
        "option": "2. Создать файл через GitHub напрямую",
        "description": "Если модуль >200KB, попросить Садовника создать его вручную",
        "workflow": "1. Сгенерировать JSON в отдельном сообщении\n2. Попросить Садовника скопировать и создать файл\n3. Продолжить работу с модулем через патчи"
      },
      {
        "option": "3. Использовать архитектуру с подмодулями",
        "description": "Вместо 1 большого → N маленьких модулей",
        "example": "simbiosis/tasks/core.json, simbiosis/tasks/archive.json"
      }
    ]
  },

  "real_world_examples": {
    "example_1_large_task_list": {
      "scenario": "Нужно создать модуль с 100 задачами",
      "wrong_way": "Создать один патч с content содержащим все 100 задач (будет обрезан)",
      "right_way": [
        "1. Создать модуль с пустым массивом tasks: []",
        "2. Добавить первые 20 задач через JSON patch (add операция)",
        "3. Добавить следующие 20 задач",
        "4. Повторить до заполнения"
      ],
      "code": {
        "step_1": {
          "file_path": "simbiosis/tasks.json",
          "content": "{\"identity\":{\"module_id\":\"TASKS-001\",\"name\":\"Tasks\",\"version\":\"1.0\"},\"meta\":{\"status\":\"active\"},\"tasks\":[]}",
          "description": "Создание базы"
        },
        "step_2": {
          "file_path": "simbiosis/tasks.json",
          "changes": [
            {"op": "add", "path": "tasks", "value": {"id": "T1", "title": "Task 1"}},
            {"op": "add", "path": "tasks", "value": {"id": "T2", "title": "Task 2"}},
            "... повторить для 20 задач"
          ],
          "description": "Добавление первых 20"
        }
      }
    },

    "example_2_documentation_module": {
      "scenario": "Создать модуль документации с большими текстами",
      "wrong_way": "Хранить весь текст в JSON",
      "right_way": [
        "1. Создать модуль с индексом документов",
        "2. Каждый документ — отдельный .md файл",
        "3. В модуле — только метаданные и ссылки"
      ],
      "structure": {
        "simbiosis/docs.json": {
          "identity": {},
          "meta": {},
          "documents": [
            {"id": "DOC-001", "title": "Guide", "file": "docs/guide.md"},
            {"id": "DOC-002", "title": "Tutorial", "file": "docs/tutorial.md"}
          ]
        },
        "docs/guide.md": "Полный текст гайда здесь...",
        "docs/tutorial.md": "Полный текст туториала здесь..."
      }
    }
  },

  "troubleshooting": {
    "symptom_1": {
      "problem": "Патч обрезается на середине JSON",
      "check": "Размер content в патче >10KB?",
      "solution": "Минифицируй JSON или разбей на части"
    },
    "symptom_2": {
      "problem": "Даже минифицированный патч обрезается",
      "check": "Размер >30KB?",
      "solution": "Используй поэтапное создание (пустая база + add операции)"
    },
    "symptom_3": {
      "problem": "Нужно создать модуль с огромным dataset",
      "solution": "Создай модуль с metadata, данные храни в отдельных файлах или используй внешнее хранилище"
    }
  },

  "limits_summary": {
    "theoretical_max": "16384 токена ≈ 60KB текста (для plain text)",
    "practical_max_json": "30-40KB (из-за escape-символов и структуры)",
    "recommended_max": "20KB на один патч (для надёжности)",
    "if_bigger": "Разбивай на несколько патчей"
  },

  "quick_checklist": [
    "[ ] JSON минифицирован (нет \\n и лишних пробелов)?",
    "[ ] Размер content <20KB?",
    "[ ] Если >20KB: разбит на части?",
    "[ ] Используются короткие ключи где возможно?",
    "[ ] Большие тексты вынесены в отдельные файлы?",
    "[ ] Модуль не дублирует данные из других модулей?"
  ],

  "message_to_sr": "При создании больших модулей ВСЕГДА минифицируй JSON в content (убери переносы и пробелы). Если модуль всё равно большой (>20KB) — создавай пустую структуру, потом заполняй через JSON patches по частям. Это позволит избежать обрезки патчей. 📦"
}

```
